func TestBcryptCompatibility(t *testing.T) {
	// Generated by the former bcryptjs implementation using a synthetic test password.
	hash := "$2b$12$LI1hoyp8VyTZwLAQaEA42.Kz5uowCc07Lot7fQDwsnOEsqiXlFdnG"
	for _, version := range []string{"$2b$", "$2a$"} {
		h := version + hash[4:]
		if err := bcrypt.CompareHashAndPassword([]byte(h), []byte("test-compat-password")); err != nil {
			t.Fatal(err)
		}
		if bcrypt.CompareHashAndPassword([]byte(h), []byte("wrong-password")) == nil {
			t.Fatal("accepted wrong password")
		}
	}
}
func TestEmailPolicy(t *testing.T) {
	for _, email := range []string{"student@example.com", "tutor@example.test", "имя@example.com"} {
		if !validEmail(email, false) {
			t.Errorf("rejected %q", email)
		}
	}
	for _, email := range []string{"supadmin@teachem", "student@host", "Display Name <x@example.com>", "x@example.com\r\n", "x@example.com "} {
		if validEmail(email, false) {
			t.Errorf("accepted %q", email)
		}
	}
	if !validEmail("supadmin@teachem", true) {
		t.Fatal("reserved owner login rejected")
	}
	if validEmail("anyone@teachem", true) {
		t.Fatal("exception broadened beyond exact login")
	}
}
func TestPasswordByteLimit(t *testing.T) {
	for _, s := range []string{"short", strings.Repeat("Ж", 37), strings.Repeat("a", 73)} {
		if passwordValue(core.Row{"password": s}, "password") == nil {
			t.Fatal("invalid password accepted")
		}
	}
	for _, s := range []string{strings.Repeat("a", 12), strings.Repeat("Ж", 36)} {
		if e := passwordValue(core.Row{"password": s}, "password"); e != nil {
			t.Fatal(e)
		}
	}
}
func TestSelfViewDoesNotExposeSecrets(t *testing.T) {
	u := core.Row{"id": "test", "name": "Original full name", "surname": "", "role": "student", "email": "a@example.test", "passwordHash": "secret", "refreshTokenHash": "secret", "mustChangePassword": true}
	view := publicSelf(u)
	if _, ok := view["passwordHash"]; ok {
		t.Fatal("passwordHash leaked")
	}
	if _, ok := view["refreshTokenHash"]; ok {
		t.Fatal("refresh hash leaked")
	}
	if view["name"] != "Original full name" || view["surname"] != "" {
		t.Fatal("name parts changed")
	}
}
func jwtContext() *core.Context {
	return &core.Context{App: &core.App{Config: core.Config{AccessSecret: strings.Repeat("a", 40), RefreshSecret: strings.Repeat("r", 40)}}, W: httptest.NewRecorder(), R: httptest.NewRequest("GET", "http://localhost/auth/me", nil)}
}
func TestJWTWireCompatibilityAndSeparation(t *testing.T) {
	c := jwtContext()
	id, sid := core.NewID(), core.NewID()
	exp := time.Now().Add(time.Hour)
	access, e := token(c, id, sid, false, exp)
	if e != nil {
		t.Fatal(e)
	}
	p, e := decode(c, access, false)
	if e != nil || p["sub"] != id || p["sid"] != sid {
		t.Fatal("token incompatible", e)
	}
	if _, e = decode(c, access, true); e == nil {
		t.Fatal("accepted access token as refresh")
	}
	refresh, e := token(c, id, sid, true, exp)
	if e != nil {
		t.Fatal(e)
	}
	if _, e = decode(c, refresh, false); e == nil {
		t.Fatal("accepted refresh token as access")
	}
	old := jwt.NewWithClaims(jwt.SigningMethodHS256, jwt.MapClaims{"sid": sid, "type": "access", "sub": id, "iss": "tutor-api", "aud": "tutor-web", "jti": core.NewID(), "iat": time.Now().Unix(), "exp": exp.Unix()})
	signed, _ := old.SignedString([]byte(c.App.Config.AccessSecret))
	if _, e = decode(c, signed, false); e != nil {
		t.Fatal("legacy JWT claims rejected", e)
	}
	for _, claims := range []jwt.MapClaims{
		{"sid": sid, "type": "access", "sub": id, "iss": "other", "aud": "tutor-web", "exp": exp.Unix()},
		{"sid": sid, "type": "access", "sub": id, "iss": "tutor-api", "aud": "other", "exp": exp.Unix()},
		{"sid": sid, "type": "access", "sub": id, "iss": "tutor-api", "aud": "tutor-web"},
		{"sid": sid, "type": "access", "sub": id, "iss": "tutor-api", "aud": "tutor-web", "exp": time.Now().Add(-time.Hour).Unix()},
	} {
		s, _ := jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString([]byte(c.App.Config.AccessSecret))
		if _, e = decode(c, s, false); e == nil {
			t.Fatal("invalid JWT accepted")
		}
	}
}
func TestProfileValidation(t *testing.T) {
	invalid := []core.Row{{"name": " "}, {"email": "supadmin@teachem"}, {"experienceYears": 1.5}, {"experienceYears": 81.0}, {"subjects": []any{""}}, {"languages": []any{1}}, {"photoAssetId": "wrong"}, {"surname": nil}}
	for _, d := range invalid {
		if profileFields(d) == nil {
			t.Fatalf("accepted invalid profile %#v", d)
		}
	}
	valid := core.Row{"name": " Original full name ", "surname": "", "subjects": []any{"Math"}, "languages": []any{}, "experienceYears": 0.0}
	if e := profileFields(valid); e != nil {
		t.Fatal(e)
	}
	if valid["name"] != "Original full name" {
		t.Fatal("wrong normalization")
	}
}
